def find_length(s: str) -> int:
    diff = [0] * len(s)
    for i in range(1, len(s)):
        if s[i] == '0' and s[i - 1] == '1':
            diff[i] = -1 + diff[i - 1]
        elif s[i] == '1' and s[i - 1] == '0':
            diff[i] = 1 + diff[i - 1]
        else:
            diff[i] = diff[i - 1]
    max_diff = max(diff)
    min_diff = min(diff)
    return max(0, max_diff - min_diff)
```

